## Reference values for validating a from-scratch Python Firth-logistic implementation.
##
## These are VALUES GENERATED BY RUNNING logistf (an R package), not values taken from a
## publication. Cite them as such: "reference values generated with logistf vX.Y (R vX.Y)",
## never as a published citation. See environment.txt for exact versions and install
## provenance, and HANDOFF.md / the user's decision of 2026-09-20 for why this is the
## PRIMARY validation source (Option 3), with the firthlogist Python package's README
## used only as a SECONDARY cross-check (Option 1).
##
## sex2: Urinary Tract Infection in American College Students (case ~ age+oc+vic+vicl+vis+dia),
## the worked example from logistf's own documentation (README.md, man/logistf.Rd).

lib <- Sys.getenv("R_LIBS_USER")
library(logistf, lib.loc = lib)

out_dir <- "src/analysis/firth_ref"

## --- Confirm the package's bundled sex2 is identical to the copy fetched independently
## from GitHub before R was installed (used earlier for structural inspection). ---
data(sex2, package = "logistf")
sex2_pkg <- sex2

tmp_env <- new.env()
load(file.path(out_dir, "sex2.rda"), envir = tmp_env)
sex2_fetched <- tmp_env$sex2

identical_data <- identical(sex2_pkg, sex2_fetched)

## --- Fit the model exactly as in logistf's own documented example ---
fit <- logistf(case ~ age + oc + vic + vicl + vis + dia, data = sex2)

## --- Two logistftest() calls, per the user's instruction: (a) one coefficient,
## (b) a group of >=2. Both follow logistf's documented convention: the restricted
## model is fit by constraining the tested coefficient(s) to 0 WITHIN the full design
## (Jeffreys penalty computed from the full model's information matrix), not by
## re-fitting a smaller Firth model from scratch. This is the convention Step 1's
## LRT (M0 vs M1) must match. ---
test_single <- logistftest(fit, test = ~ dia - 1)         # single coefficient: dia = 0
test_joint <- logistftest(fit, test = ~ vic + vicl - 1)   # joint: vic = 0 AND vicl = 0

## --- Full human-readable transcript ---
sink(file.path(out_dir, "sex2_reference_output.txt"))
cat("R version:", R.version.string, "\n")
cat("logistf version:", as.character(packageVersion("logistf")), "\n")
cat("sex2 (bundled with logistf) identical to sex2 fetched from GitHub raw:", identical_data, "\n\n")

cat("=== Model: case ~ age + oc + vic + vicl + vis + dia ===\n\n")
cat("--- summary(fit) ---\n")
print(summary(fit))

cat("\n--- print(fit) (includes overall penalized LRT) ---\n")
print(fit)

cat("\n--- coefficients ---\n")
print(fit$coefficients)

cat("\n--- standard errors, sqrt(diag(fit$var)) ---\n")
print(sqrt(diag(fit$var)))

cat("\n--- penalized log-likelihoods (fit$loglik) ---\n")
print(fit$loglik)

cat("\n--- per-coefficient penalized profile-LR p-values (fit$prob) ---\n")
print(fit$prob)

cat("\n\n=== logistftest: single coefficient, dia = 0 ===\n")
print(test_single)

cat("\n\n=== logistftest: joint, vic = 0 AND vicl = 0 ===\n")
print(test_joint)
sink()

## --- Machine-readable numeric outputs for the Python comparison script ---
coefs <- data.frame(
  term = names(fit$coefficients),
  estimate = as.numeric(fit$coefficients),
  se = as.numeric(sqrt(diag(fit$var))),
  penalized_LR_p = as.numeric(fit$prob)
)
write.csv(coefs, file.path(out_dir, "sex2_reference_coefs.csv"), row.names = FALSE)

## NOTE on logistftest()'s $loglik naming: the element named "null" is actually the
## RESTRICTED model (tested coefficient(s) fixed), and "full" is the unrestricted model
## -- confirmed by reading R/print.logistftest.R, which maps loglik['null'] to the
## printed label "Restricted model" and loglik['full'] to "Full model". Do not index
## this vector positionally; use the names.
scalars <- data.frame(
  quantity = c(
    "loglik_full", "loglik_null",
    "single_test_restricted_loglik", "single_test_full_loglik", "single_test_LR_stat",
    "single_test_df", "single_test_p",
    "joint_test_restricted_loglik", "joint_test_full_loglik", "joint_test_LR_stat",
    "joint_test_df", "joint_test_p"
  ),
  value = c(
    unname(fit$loglik["full"]), unname(fit$loglik["null"]),
    unname(test_single$loglik["null"]), unname(test_single$loglik["full"]),
    unname(2 * (test_single$loglik["full"] - test_single$loglik["null"])),
    unname(test_single$df), unname(test_single$prob),
    unname(test_joint$loglik["null"]), unname(test_joint$loglik["full"]),
    unname(2 * (test_joint$loglik["full"] - test_joint$loglik["null"])),
    unname(test_joint$df), unname(test_joint$prob)
  )
)
write.csv(scalars, file.path(out_dir, "sex2_reference_scalars.csv"), row.names = FALSE)

cat("Wrote sex2_reference_output.txt, sex2_reference_coefs.csv, sex2_reference_scalars.csv to",
    out_dir, "\n")
cat("sex2 data identity check (package vs GitHub fetch):", identical_data, "\n")
